// Des: Human-like mouse curves, clicks, typing and scrolling over CDP
// Flo: plan bezier path or key ops > pause with log-normal delays > dispatch trusted Input events
// I/O: Conn + Random + points or text (caller) > mouse/key/wheel events in the page
// ===================================================================
const std = @import("std"); const cdp = @import("nt-cdpz-sock.zig"); const snap = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig");
const CF = .{ .calz = 15000, .stpz = 3, .stpm = 28, .pxst = 22.0, .hopz = 10, .hope = 24, .thkp = 8, .thkl = 300, .thkh = 900, .prel = 60, .preh = 180, .hldl = 40, .hldh = 120, .tick = 100 };
pub const Pt = snap.Pt;
pub const Op = struct { kind: enum { key, ins, ent }, txt: []const u8 };
fn dist(one: Pt, two: Pt) f64 { return @sqrt((one.x - two.x) * (one.x - two.x) + (one.y - two.y) * (one.y - two.y)); }
pub fn stepsFor(from: Pt, to: Pt) u32 { const raw: u32 = @intFromFloat(@min(@as(f64, CF.stpm), dist(from, to) / CF.pxst)); return @max(CF.stpz, raw); }
pub fn curve(aren: std.mem.Allocator, from: Pt, to: Pt, rand: std.Random) ![]Pt { const num = stepsFor(from, to); const dxz = to.x - from.x; const dyz = to.y - from.y; const lenz = @max(1.0, @sqrt(dxz * dxz + dyz * dyz)); const nx = -dyz / lenz; const ny = dxz / lenz; const cap: f64 = if (lenz < 100) 3.0 else lenz * 0.2; const off1 = (rand.float(f64) - 0.5) * 2.0 * cap; const off2 = (rand.float(f64) - 0.5) * 1.5 * cap; const c1: Pt = .{ .x = from.x + dxz * 0.3 + nx * off1, .y = from.y + dyz * 0.3 + ny * off1 }; const c2: Pt = .{ .x = from.x + dxz * 0.7 + nx * off2, .y = from.y + dyz * 0.7 + ny * off2 }; const out = try aren.alloc(Pt, num); for (out, 0..) |*pnt, idx| { const rat: f64 = @as(f64, @floatFromInt(idx + 1)) / @as(f64, @floatFromInt(num)); const tee = (1.0 - @cos(std.math.pi * rat)) / 2.0; const uu = 1.0 - tee; pnt.x = uu * uu * uu * from.x + 3 * uu * uu * tee * c1.x + 3 * uu * tee * tee * c2.x + tee * tee * tee * to.x; pnt.y = uu * uu * uu * from.y + 3 * uu * uu * tee * c1.y + 3 * uu * tee * tee * c2.y + tee * tee * tee * to.y; } out[num - 1] = to; return out; }
pub fn planType(aren: std.mem.Allocator, text: []const u8) ![]Op { var out: std.ArrayList(Op) = .empty; var itr = (try std.unicode.Utf8View.init(text)).iterator(); while (itr.nextCodepointSlice()) |sli| { if (sli.len == 1 and sli[0] == '\n') { try out.append(aren, .{ .kind = .ent, .txt = sli }); } else if (sli.len == 1 and sli[0] >= 0x20 and sli[0] < 0x7f) { try out.append(aren, .{ .kind = .key, .txt = sli }); } else if (sli.len == 1 and sli[0] < 0x20) { continue; } else { try out.append(aren, .{ .kind = .ins, .txt = sli }); } } return out.items; }
fn nap(conn: *cdp.Conn, mill: u32) void { std.Io.sleep(conn.iozz, .fromMilliseconds(mill), .awake) catch {}; }
fn mouse(aren: std.mem.Allocator, conn: *cdp.Conn, kind: []const u8, pnt: Pt, extr: []const u8) !void { const par = try std.fmt.allocPrint(aren, "{{\"type\":\"{s}\",\"x\":{d:.1},\"y\":{d:.1}{s}}}", .{ kind, pnt.x, pnt.y, extr }); _ = try conn.callJson(aren, "Input.dispatchMouseEvent", par, CF.calz); }
pub fn moveTo(aren: std.mem.Allocator, conn: *cdp.Conn, rand: std.Random, from: Pt, to: Pt) !Pt { const path = try curve(aren, from, to, rand); for (path) |pnt| { try mouse(aren, conn, "mouseMoved", pnt, ""); nap(conn, pace.delayLogn(rand, CF.hopz, CF.hope)); } return to; }
pub fn clickAt(aren: std.mem.Allocator, conn: *cdp.Conn, rand: std.Random, from: Pt, to: Pt) !Pt { const pos = try moveTo(aren, conn, rand, from, to); nap(conn, pace.delayLogn(rand, CF.prel, CF.preh)); try mouse(aren, conn, "mousePressed", pos, ",\"button\":\"left\",\"clickCount\":1"); nap(conn, pace.delayLogn(rand, CF.hldl, CF.hldh)); try mouse(aren, conn, "mouseReleased", pos, ",\"button\":\"left\",\"clickCount\":1"); return pos; }
fn keyEvt(aren: std.mem.Allocator, conn: *cdp.Conn, kind: []const u8, txt: []const u8, extr: []const u8) !void { const quo = try std.json.Stringify.valueAlloc(aren, txt, .{}); const par = try std.fmt.allocPrint(aren, "{{\"type\":\"{s}\",\"key\":{s},\"text\":{s},\"unmodifiedText\":{s}{s}}}", .{ kind, quo, quo, quo, extr }); _ = try conn.callJson(aren, "Input.dispatchKeyEvent", par, CF.calz); }
pub fn typeText(aren: std.mem.Allocator, conn: *cdp.Conn, rand: std.Random, text: []const u8, lowz: u32, higz: u32) !void { const ops = try planType(aren, text); for (ops) |opz| { switch (opz.kind) { .key => { try keyEvt(aren, conn, "keyDown", opz.txt, ""); try keyEvt(aren, conn, "keyUp", opz.txt, ""); }, .ins => { const quo = try std.json.Stringify.valueAlloc(aren, opz.txt, .{}); const par = try std.fmt.allocPrint(aren, "{{\"text\":{s}}}", .{quo}); _ = try conn.callJson(aren, "Input.insertText", par, CF.calz); }, .ent => { const par = "{\"type\":\"rawKeyDown\",\"key\":\"Enter\",\"code\":\"Enter\",\"windowsVirtualKeyCode\":13,\"modifiers\":8}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", par, CF.calz); const par2 = "{\"type\":\"keyUp\",\"key\":\"Enter\",\"code\":\"Enter\",\"windowsVirtualKeyCode\":13,\"modifiers\":8}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", par2, CF.calz); } } nap(conn, pace.delayLogn(rand, lowz, higz)); if (opz.txt[0] == ' ' and rand.uintLessThan(u32, 100) < CF.thkp) nap(conn, pace.delayLogn(rand, CF.thkl, CF.thkh)); } }
pub fn clearField(aren: std.mem.Allocator, conn: *cdp.Conn) !void { const sel = "{\"type\":\"rawKeyDown\",\"key\":\"a\",\"code\":\"KeyA\",\"windowsVirtualKeyCode\":65,\"modifiers\":2,\"commands\":[\"selectAll\"]}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", sel, CF.calz); const del = "{\"type\":\"rawKeyDown\",\"key\":\"Backspace\",\"code\":\"Backspace\",\"windowsVirtualKeyCode\":8}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", del, CF.calz); const up = "{\"type\":\"keyUp\",\"key\":\"Backspace\",\"code\":\"Backspace\",\"windowsVirtualKeyCode\":8}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", up, CF.calz); }
pub fn scrollBy(aren: std.mem.Allocator, conn: *cdp.Conn, rand: std.Random, at: Pt, deltay: i32) !void { var left: i32 = deltay; while (left != 0) { const tick: i32 = if (left > 0) @min(left, CF.tick) else @max(left, -CF.tick); const par = try std.fmt.allocPrint(aren, "{{\"type\":\"mouseWheel\",\"x\":{d:.1},\"y\":{d:.1},\"deltaX\":0,\"deltaY\":{d}}}", .{ at.x, at.y, tick }); _ = try conn.callJson(aren, "Input.dispatchMouseEvent", par, CF.calz); left -= tick; nap(conn, pace.delayLogn(rand, 40, 160)); } }
pub fn pauseAct(conn: *cdp.Conn, rand: std.Random, lows: u32, higs: u32) u32 { const mill = pace.delayLogn(rand, lows * 1000, higs * 1000); nap(conn, mill); return mill; }
pub fn pauseMsec(conn: *cdp.Conn, rand: std.Random, lowm: u32, higm: u32) u32 { const mill = pace.delayLogn(rand, lowm, higm); nap(conn, mill); return mill; }
